import java.util.Scanner;

public class Main {
    static long modExponent(long base, long exponent, long modulus) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % modulus;
            }
            base = (base * base) % modulus;
            exponent >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        final long MOD = 1000000007;
        while (scanner.hasNextLong()) {
            long p = scanner.nextLong();
            long k = scanner.nextLong();

            if (k == 0) {
                System.out.println(modExponent(p, p - 1, MOD));
                continue;
            }
            if (k == 1) {
                System.out.println(modExponent(p, p, MOD));
                continue;
            }

            long count = 0;
            long current_value = 1;
            long next_value = -1;

            do {
                next_value = (k * current_value) % p;
                current_value = next_value;
                count++;
            } while (next_value != 1);

            System.out.println(modExponent(p, (p - 1) / count, MOD));
        }
        scanner.close();
    }
}
